(function(E){ const x = E["exam-01"] = E["exam-01"] || {units:{}}; (x.units = x.units || {})["x01-w2"] = {"id":"x01-w2","patterns":["W2-opinion","W2T-cities","TR-halfquestion"],"title":{"en":"Writing Task 2","tr":"Writing Task 2","fa":"Writing Task 2 (نوشتن، تکلیف ۲)"},"objective":{"en":"In this lesson you will learn to plan and write an opinion essay of at least 250 words: say how far you agree, support your view with two developed reasons and examples, and keep one position to the end.","tr":"Bu derste en az 250 kelimelik bir görüş yazısını planlayıp yazmayı öğreneceksin: ne ölçüde katıldığını söyleyecek, görüşünü iki gelişmiş neden ve örnekle destekleyecek ve sona kadar tek bir tutumu koruyacaksın.","fa":"در این درس یاد می‌گیری یک مقاله‌ی نظری دست‌کم ۲۵۰ کلمه‌ای را برنامه‌ریزی کنی و بنویسی: بگویی تا چه حد موافقی، نظرت را با دو دلیل که خوب توضیحشان داده‌ای و با مثال پشتیبانی کنی و تا آخر یک موضع را نگه داری."},"sessions":[["explain"],["writing"],["exit"]],"explain":{"title":{"en":"Writing Task 2: an opinion essay","tr":"Writing Task 2: bir görüş yazısı","fa":"Writing Task 2: مقاله‌ی نظری"},"objective":{"en":"In this lesson you will learn to plan and write an opinion essay of at least 250 words: say how far you agree, support your view with two developed reasons and examples, and keep one position to the end.","tr":"Bu derste en az 250 kelimelik bir görüş yazısını planlayıp yazmayı öğreneceksin: ne ölçüde katıldığını söyleyecek, görüşünü iki gelişmiş neden ve örnekle destekleyecek ve sona kadar tek bir tutumu koruyacaksın.","fa":"در این درس یاد می‌گیری یک مقاله‌ی نظری دست‌کم ۲۵۰ کلمه‌ای را برنامه‌ریزی کنی و بنویسی: بگویی تا چه حد موافقی، نظرت را با دو دلیل که خوب توضیحشان داده‌ای و با مثال پشتیبانی کنی و تا آخر یک موضع را نگه داری."},"stats":[{"label":{"en":"Words","tr":"Kelime","fa":"کلمه"},"value":"250+"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"40 min","tr":"40 dk","fa":"۴۰ دقیقه"}},{"label":{"en":"Paragraphs","tr":"Paragraf","fa":"پاراگراف"},"value":"4-5"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: tall buildings and the housing shortage","tr":"Bu sınav: yüksek binalar ve konut yetersizliği","fa":"این آزمون: ساختمان‌های بلند و کمبود مسکن"},"intro":{"en":"\"To what extent do you agree or disagree?\" is the most common Task 2 question. The topics are everyday issues: work, education, cities, technology. You do not need special knowledge, only clear reasons and examples.","tr":"\"To what extent do you agree or disagree?\" en sık çıkan Task 2 sorusudur. Konular günlük meselelerdir: iş, eğitim, şehirler, teknoloji. Özel bir bilgiye gerek yok; yalnızca net nedenler ve örnekler.","fa":"«To what extent do you agree or disagree?» رایج‌ترین سؤال Task 2 است. موضوع‌ها مسائل روزمره‌اند: کار، آموزش، شهر، فناوری. دانش تخصصی لازم نیست، فقط دلیل‌ها و مثال‌های روشن."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x01-w2-ctx","exam":true,"patterns":["W2-opinion","W2T-cities"],"often":{"pattern":"W2-opinion","n":20,"of":76,"label":{"en":"Comes up often in the real exam: 20 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 20’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۲۰ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}},"title":{"en":"Opinion essay: tall buildings and housing","tr":"Görüş yazısı: yüksek binalar ve konut","fa":"مقاله‌ی نظری: ساختمان‌های بلند و مسکن"},"asks":{"en":"The question gives one claim about cities and housing and asks how far you agree. You choose a clear position and keep it from the introduction to the conclusion.","tr":"Soru şehirler ve konut hakkında bir iddia veriyor ve ne ölçüde katıldığını soruyor. Net bir tutum seçer ve onu girişten sonuca kadar korursun.","fa":"سؤال یک ادعا درباره‌ی شهرها و مسکن می‌دهد و می‌پرسد تا چه حد موافقی. یک موضع روشن انتخاب می‌کنی و آن را از مقدمه تا نتیجه حفظ می‌کنی."},"fields":["The claim","Your position","Reason 1 + example","Reason 2 + example","The other side (optional)","Conclusion"],"words":[{"a":"tall buildings","b":"high-rise blocks / tower blocks","tr":"yüksek binalar","fa":"ساختمان‌های بلند"},{"a":"not enough homes","b":"a housing shortage","tr":"konut yetersizliği","fa":"کمبود مسکن"},{"a":"more people in less space","b":"higher density","tr":"daha yüksek yoğunluk","fa":"تراکم بیشتر"},{"a":"cheap to rent or buy","b":"affordable","tr":"uygun fiyatlı","fa":"مقرون‌به‌صرفه"},{"a":"the edge of the city","b":"the outskirts / the suburbs","tr":"şehrin kenarı, banliyöler","fa":"حومه‌ی شهر"},{"a":"roads, schools, transport","b":"infrastructure / public services","tr":"altyapı","fa":"زیرساخت"},{"a":"green areas","b":"parks and open spaces","tr":"yeşil alanlar","fa":"فضای سبز"},{"a":"people who live there","b":"residents / the community","tr":"sakinler","fa":"ساکنان"},{"a":"I partly agree","b":"to some extent / up to a point","tr":"kısmen katılıyorum","fa":"تا حدی موافقم"},{"a":"but","b":"however / although / on the other hand","tr":"ama","fa":"اما"},{"a":"for example","b":"for instance / a good example is","tr":"örneğin","fa":"برای مثال"},{"a":"the best way","b":"the most effective solution","tr":"en iyi yol","fa":"بهترین راه"}],"traps":[{"en":"Answering a different question: writing about the history of cities instead of whether tall buildings are the best answer to a housing shortage.","tr":"Başka bir soruyu cevaplamak: yüksek binaların konut yetersizliğine en iyi çözüm olup olmadığı yerine şehirlerin tarihini yazmak.","fa":"جواب دادن به سؤالی دیگر: نوشتن درباره‌ی تاریخ شهرها به جای اینکه آیا ساختمان بلند بهترین راه حل کمبود مسکن است یا نه."},{"en":"Changing position: agreeing in the introduction and disagreeing in the conclusion.","tr":"Tutum değiştirmek: girişte katılıp sonuçta karşı çıkmak.","fa":"عوض کردن موضع: در مقدمه موافق بودن و در نتیجه مخالف."},{"en":"Ignoring \"the best way\": the claim is not only that towers help, but that they are better than every other solution.","tr":"\"The best way\"i görmezden gelmek: iddia yalnızca kulelerin işe yaradığı değil, diğer bütün çözümlerden daha iyi oldukları.","fa":"نادیده گرفتن «the best way»: ادعا فقط این نیست که برج‌ها کمک می‌کنند، بلکه اینکه از همه‌ی راه‌حل‌های دیگر بهترند."}],"ideas":["Towers house many families on a small piece of land near jobs and transport.","Building upwards protects countryside and farmland from new suburbs.","Very tall towers are expensive to build and maintain, so flats may not be affordable.","Residents can feel isolated; families with children often need outdoor space.","Medium-rise blocks (five to eight floors) can reach a similar density.","Empty offices and unused buildings can be turned into homes.","Rent controls and public housing affect prices more than the height of buildings."],"example":{"text":"Question: \"Cities should ban cars from their centres. To what extent do you agree or disagree?\"","item":"Which sentence states a clear position?","answer":"Although a complete ban would be difficult for some groups, I largely agree, because car-free centres are cleaner, safer and better for local shops.","why":{"en":"It answers \"to what extent\" (largely agree), admits the other side and gives the main reasons in one sentence.","tr":"\"Ne ölçüde\" sorusunu cevaplıyor (büyük ölçüde katılıyorum), karşı tarafı kabul ediyor ve ana nedenleri tek cümlede veriyor.","fa":"به «تا چه حد» جواب می‌دهد (تا حد زیادی موافقم)، طرف مقابل را هم می‌پذیرد و دلیل‌های اصلی را در یک جمله می‌گوید."}}},{"id":"W2T-cities","ctx":["W2-problem","W2-twopart","W2T-cities"],"title":{"en":"Cities, housing, travel and tourism","tr":"Şehirler, konut, seyahat ve turizm","fa":"شهرها، مسکن، سفر و گردشگری"},"asks":{"en":"Questions about where and how people live and travel: tall buildings, moving to cities, renting or buying, tourism to remote places, holidays at home or abroad, building homes in the countryside.","tr":"İnsanların nerede ve nasıl yaşadığı ve seyahat ettiği üzerine sorular: yüksek binalar, şehre göç, kiralamak ya da satın almak, uzak yerlere turizm, yurt içinde ya da yurt dışında tatil, kırsalda konut yapımı.","fa":"سؤال‌هایی درباره‌ی اینکه مردم کجا و چطور زندگی و سفر می‌کنند: ساختمان‌های بلند، مهاجرت به شهرها، اجاره یا خرید خانه، گردشگری در جاهای دورافتاده، تعطیلات در داخل یا خارج، ساخت خانه در روستا."},"fields":["Traffic in cities is getting worse. Causes and solutions?","Why do people move to cities, and what problems does this cause?","Should homes be built in the countryside to solve housing shortages?","Tourism to remote places: advantages and disadvantages?","Holidays at home or abroad?"],"words":[{"a":"big cities","b":"urban areas / large cities","tr":"kentsel alanlar","fa":"مناطق شهری"},{"a":"villages","b":"rural areas / the countryside","tr":"kırsal kesim","fa":"مناطق روستایی"},{"a":"moving to cities","b":"urbanisation / migration to cities","tr":"kentleşme","fa":"شهرنشینی"},{"a":"not enough homes","b":"a housing shortage","tr":"konut sıkıntısı","fa":"کمبود مسکن"},{"a":"rent","b":"rented accommodation","tr":"kiralık konut","fa":"مسکن اجاره‌ای"},{"a":"too many cars","b":"traffic congestion","tr":"trafik sıkışıklığı","fa":"ترافیک سنگین"},{"a":"buses and trains","b":"public transport","tr":"toplu taşıma","fa":"حمل‌ونقل عمومی"},{"a":"tall buildings","b":"high-rise blocks","tr":"yüksek binalar","fa":"برج‌ها"},{"a":"tourists","b":"visitors / the tourism industry","tr":"turizm sektörü","fa":"صنعت گردشگری"},{"a":"local people","b":"residents / local communities","tr":"yerel halk","fa":"ساکنان محلی"},{"a":"pay too much","b":"the cost of living","tr":"hayat pahalılığı","fa":"هزینه‌ی زندگی"},{"a":"green areas","b":"parks and open spaces","tr":"yeşil alanlar","fa":"فضای سبز"}],"traps":[{"en":"Problem and solution questions: each solution must match a cause you gave, not a new problem.","tr":"Sorun-çözüm sorularında her çözüm, verdiğin bir nedene karşılık gelmeli; yeni bir soruna değil.","fa":"در سؤال‌های مشکل و راه‌حل، هر راه‌حل باید به علتی که گفتی مربوط باشد، نه به مشکلی تازه."},{"en":"Two-part questions: answer both questions directly, one paragraph each.","tr":"İki bölümlü sorular: iki soruya da doğrudan, her birine bir paragraf ayırarak cevap ver.","fa":"سؤال‌های دوبخشی: به هر دو سؤال مستقیم جواب بده، هر کدام یک پاراگراف."}],"example":{"text":"Question: In many countries, young people cannot afford to buy a home. Why is this? What can be done about it?","item":"Write a thesis sentence that answers both parts.","answer":"Young people are priced out mainly because house prices have risen far faster than wages, and governments could help by building more affordable homes and controlling rents.","why":{"en":"One sentence, both parts: the main cause and two matching solutions.","tr":"Tek cümle, iki bölüm: ana neden ve ona uyan iki çözüm.","fa":"یک جمله، هر دو بخش: علت اصلی و دو راه‌حل متناسب با آن."}},"ideas":["+ Better public transport reduces both traffic and pollution.","- Building more roads often attracts more cars.","+ Cities offer jobs, universities and hospitals.","- Rapid growth leads to housing shortages and slums.","+ Tourism brings income to remote regions.","- Too many visitors damage fragile places and raise local prices."],"general":true,"patterns":["W2-problem","W2-twopart","W2T-cities"],"often":{"pattern":"W2T-cities","n":7,"of":76,"label":{"en":"Comes up often in the real exam: 7 of the last 76 Task 2 questions","tr":"Gerçek sınavda sık çıkar: son 76 Task 2 sorusunun 7’sinde","fa":"در آزمون واقعی زیاد می‌آید: در ۷ سؤال از ۷۶ سؤالِ اخیرِ Task 2"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Forty minutes, one position","tr":"Kırk dakika, tek tutum","fa":"چهل دقیقه، یک موضع"},"body":{"en":"Write at least 250 words in about 40 minutes. Use about 5 minutes to plan, 30 to write and 5 to check. The essay needs an introduction with your position, two or three body paragraphs and a short conclusion.","tr":"Yaklaşık 40 dakikada en az 250 kelime yaz. Yaklaşık 5 dakika plan, 30 dakika yazma ve 5 dakika kontrol için kullan. Yazının tutumunu içeren bir girişe, iki üç gövde paragrafına ve kısa bir sonuca ihtiyacı var.","fa":"در حدود ۴۰ دقیقه دست‌کم ۲۵۰ کلمه بنویس. حدود ۵ دقیقه برای برنامه‌ریزی، ۳۰ دقیقه برای نوشتن و ۵ دقیقه برای بازبینی بگذار. مقاله به مقدمه‌ای با موضع تو، دو سه پاراگراف بدنه و یک نتیجه‌ی کوتاه نیاز دارد."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Plan in four steps","tr":"Dört adımda plan","fa":"برنامه‌ریزی در چهار قدم"},"steps":[{"en":"Underline the claim and the key words, such as \"the best way\".","tr":"İddianın ve \"the best way\" gibi anahtar kelimelerin altını çiz.","fa":"زیر ادعا و کلمه‌های کلیدی مثل «the best way» خط بکش."},{"en":"Decide your position: agree, disagree, or agree up to a point.","tr":"Tutumuna karar ver: katılıyorum, katılmıyorum ya da bir noktaya kadar katılıyorum.","fa":"موضعت را مشخص کن: موافق، مخالف یا تا حدی موافق."},{"en":"Choose two reasons and one real example for each.","tr":"İki neden ve her biri için gerçek bir örnek seç.","fa":"دو دلیل و برای هر کدام یک مثال واقعی انتخاب کن."},{"en":"Give each reason its own paragraph: point, explanation, example.","tr":"Her nedene kendi paragrafını ver: fikir, açıklama, örnek.","fa":"به هر دلیل پاراگراف خودش را بده: ایده، توضیح، مثال."}]},{"eyebrow":{"en":"The language","tr":"Dil","fa":"زبان"},"head":{"en":"Saying how far you agree","tr":"Ne ölçüde katıldığını söylemek","fa":"گفتن اینکه تا چه حد موافقی"},"table":{"headers":{"en":["Position","Phrase"],"tr":["Tutum","İfade"],"fa":["موضع","عبارت"]},"rows":[["agree","I strongly agree that..."],["partly agree","I agree up to a point, but..."],["disagree","I do not believe that... because..."],["admit the other side","It is true that... However,..."],["conclude","For these reasons, I believe that..."]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"A body paragraph, step by step","tr":"Bir gövde paragrafı, adım adım","fa":"یک پاراگراف بدنه، قدم به قدم"},"instruction":"Question: \"Cities should ban cars from their centres. To what extent do you agree or disagree?\"","item":"Write the first body paragraph.","answer":"The main reason I support car-free centres is that they are healthier. Without traffic, the air is cleaner and people walk or cycle more. For example, several European cities that have closed central streets to cars have reported fewer road accidents and busier pavements.","walk":[{"en":"Point: the first sentence gives the reason.","tr":"Fikir: ilk cümle nedeni verir.","fa":"ایده: جمله‌ی اول دلیل را می‌گوید."},{"en":"Explanation: the second sentence says why it is true.","tr":"Açıklama: ikinci cümle bunun neden doğru olduğunu söyler.","fa":"توضیح: جمله‌ی دوم می‌گوید چرا درست است."},{"en":"Example: the third sentence makes it concrete.","tr":"Örnek: üçüncü cümle onu somutlaştırır.","fa":"مثال: جمله‌ی سوم آن را ملموس می‌کند."}]},"quick":{"prompt":"Question: \"...To what extent do you agree or disagree?\" Which introduction answers it?","options":["There are many opinions about this topic.","I largely disagree, for two main reasons.","This essay will discuss cities."],"correct":1,"why":{"en":"Only \"I largely disagree...\" gives a position. The others delay the answer.","tr":"Yalnızca \"I largely disagree...\" bir tutum veriyor. Diğerleri cevabı erteliyor.","fa":"فقط «I largely disagree...» موضع می‌دهد. بقیه جواب را عقب می‌اندازند."}},"remember":{"en":"Answer the exact question, take one position, and give every reason a paragraph and an example.","tr":"Tam olarak sorulan soruyu cevapla, tek bir tutum al ve her nedene bir paragraf ve bir örnek ver.","fa":"دقیقاً به همان سؤال جواب بده، یک موضع بگیر و به هر دلیل یک پاراگراف و یک مثال بده."},"type":"explain","id":"c-x01-w2-e","course":"ielts-exams","exam":"exam-01","unit":"x01-w2"},"writing":{"taskKind":"exam","title":{"en":"Write the essay: tall buildings and housing","tr":"Yazıyı yaz: yüksek binalar ve konut","fa":"مقاله را بنویس: ساختمان‌های بلند و مسکن"},"task":"task2","reviewLabel":{"en":"Exam 1 · Writing Task 2 (opinion: tall apartment blocks and the housing shortage)"},"timed":40,"minWords":250,"ctx":["W2-opinion","W2T-cities"],"prompt":{"en":"You should spend about 40 minutes on this task. Write about the following topic: In many cities, old low-rise housing is being replaced by tall apartment blocks so that more people can live in the centre. Some people believe this is the best way to solve a city’s housing shortage. To what extent do you agree or disagree? Give reasons for your answer and include any relevant examples from your own knowledge or experience. Write at least 250 words.","tr":"Bu göreve yaklaşık 40 dakika ayırmalısın. Şu konu hakkında yaz: Birçok şehirde eski alçak katlı konutlar, merkezde daha fazla insan yaşayabilsin diye yüksek apartman bloklarıyla değiştiriliyor. Bazı insanlar bunun bir şehrin konut yetersizliğini çözmenin en iyi yolu olduğuna inanıyor. Buna ne ölçüde katılıyorsun? Cevabını gerekçelendir ve kendi bilgi ya da deneyimlerinden ilgili örnekler ver. En az 250 kelime yaz.","fa":"باید حدود ۴۰ دقیقه برای این تکلیف وقت بگذاری. درباره‌ی این موضوع بنویس: در خیلی از شهرها خانه‌های قدیمیِ کم‌طبقه با برج‌های مسکونی بلند جایگزین می‌شوند تا آدم‌های بیشتری بتوانند در مرکز شهر زندگی کنند. بعضی‌ها معتقدند این بهترین راه حل کمبود مسکن در شهر است. تا چه حد موافق یا مخالفی؟ برای جوابت دلیل بیاور و از دانسته‌ها یا تجربه‌ی خودت مثال‌های مرتبط بزن. دست‌کم ۲۵۰ کلمه بنویس."},"model":"In many growing cities, rows of old two-storey houses are being knocked down and replaced by apartment towers of twenty floors or more. Supporters argue that this is the best way to end a housing shortage. While I accept that tall buildings can provide a large number of homes, I do not believe they are the best solution, because they are often expensive and there are other ways to house people well.\n\nIt is true that high-rise blocks have one clear advantage: they fit many families onto a small piece of land. In a city centre, where land is scarce, a single tower can contain hundreds of flats close to jobs, shops and public transport. This also protects the countryside around the city from being covered by new suburbs.\n\nHowever, very tall buildings are costly to build and to run. They need lifts, special fire safety systems and constant maintenance, and these costs are usually passed on to the people who live there. As a result, many new towers in cities such as London offer flats that ordinary workers cannot afford, which does little to solve the real shortage.\n\nMoreover, a city can reach a similar density without building upwards. Blocks of five to eight floors, arranged around shared courtyards, can house almost as many people per hectare as towers, and they give families safe outdoor space for children. Turning empty offices into flats and investing in public housing can also add homes quickly.\n\nIn conclusion, although tall apartment blocks can be part of the answer, I disagree that they are the best way to solve a housing shortage. Affordable medium-rise housing, together with better use of existing buildings, is likely to do more for the people who need homes most.","moves":[{"label":{"en":"1 Introduction: the claim in your words + your position","tr":"1 Giriş: kendi kelimelerinle iddia + tutumun","fa":"۱ مقدمه: ادعا با کلمه‌های خودت + موضعت"},"text":"While I accept that tall buildings can provide a large number of homes, I do not believe they are the best solution..."},{"label":{"en":"2 The other side, admitted","tr":"2 Karşı taraf, kabul edilmiş","fa":"۲ پذیرفتن طرف مقابل"},"text":"It is true that high-rise blocks have one clear advantage..."},{"label":{"en":"3 Reason 1 + example","tr":"3 Neden 1 + örnek","fa":"۳ دلیل ۱ + مثال"},"text":"However, very tall buildings are costly to build and to run... many new towers in cities such as London..."},{"label":{"en":"4 Reason 2 + example","tr":"4 Neden 2 + örnek","fa":"۴ دلیل ۲ + مثال"},"text":"Moreover, a city can reach a similar density without building upwards..."},{"label":{"en":"5 Conclusion: the same position","tr":"5 Sonuç: aynı tutum","fa":"۵ نتیجه: همان موضع"},"text":"In conclusion, although tall apartment blocks can be part of the answer, I disagree..."}],"rubric":["Covers the task: every part of the question answered, one clear position, ideas explained and supported.","Organised: introduction, body paragraphs with one main idea each, conclusion; linking that sounds natural.","Words: topic words used precisely and naturally; the question paraphrased, not copied.","Sentences: a range of sentence types, mostly accurate; articles, agreement and punctuation checked."],"rubricI18n":{"tr":["Görevi karşılıyor: sorunun her kısmı cevaplanmış, tek ve net bir tutum, fikirler açıklanmış ve desteklenmiş.","Düzenli: giriş, her biri tek ana fikirli gövde paragrafları, sonuç; doğal görünen bağlantılar.","Kelimeler: konu kelimeleri yerinde ve doğal kullanılmış; soru kopyalanmamış, başka sözcüklerle anlatılmış.","Cümleler: çeşitli cümle türleri, çoğunlukla doğru; tanımlıklar, özne-yüklem uyumu ve noktalama kontrol edilmiş."],"fa":["تکلیف را پوشش می‌دهد: به همه‌ی بخش‌های سؤال جواب داده، یک موضع روشن دارد، ایده‌ها توضیح و پشتوانه دارند.","منظم است: مقدمه، پاراگراف‌هایی که هرکدام یک ایده‌ی اصلی دارند، نتیجه‌گیری؛ ربط‌دهنده‌هایی که طبیعی‌اند.","کلمه‌ها: کلمه‌های موضوعی دقیق و طبیعی به کار رفته‌اند؛ سؤال با کلمه‌های دیگر بیان شده، نه کپی.","جمله‌ها: انواع مختلف جمله، بیشترشان درست؛ حرف تعریف، مطابقت فعل و فاعل و نشانه‌گذاری بررسی شده."]},"rubricBands":{"note":{"en":"Score each line from 0 to 3. Read the line for the score you choose: it tells you what to improve next.","tr":"Her satırı 0’dan 3’e puanla. Seçtiğin puanın satırını oku: bir sonraki adımda neyi geliştireceğini söyler.","fa":"به هر خط از ۰ تا ۳ نمره بده. توضیحِ نمره‌ای را که انتخاب می‌کنی بخوان: می‌گوید قدم بعدی چه چیزی را بهتر کنی."},"order":["task","organised","words","sentences"],"task":[{"en":"The question is not really answered; no clear position.","tr":"Soru tam olarak cevaplanmamış; net bir tutum yok.","fa":"در واقع به سؤال جواب داده نشده؛ موضع روشنی نیست."},{"en":"A position, but only part of the question is answered, or ideas are not explained.","tr":"Bir tutum var ama sorunun yalnızca bir kısmı cevaplanmış ya da fikirler açıklanmamış.","fa":"موضعی هست، اما فقط بخشی از سؤال جواب داده شده یا ایده‌ها توضیح داده نشده‌اند."},{"en":"Every part answered, one clear position, main ideas supported.","tr":"Her kısım cevaplanmış, tek ve net bir tutum, ana fikirler desteklenmiş.","fa":"به همه‌ی بخش‌ها جواب داده شده، یک موضع روشن هست و ایده‌های اصلی پشتیبانی شده‌اند."},{"en":"A clear, consistent position; ideas fully explained with relevant examples.","tr":"Net ve tutarlı bir tutum; fikirler yerinde örneklerle tam açıklanmış.","fa":"موضعی روشن و یکدست؛ ایده‌ها با مثال‌های مرتبط کامل توضیح داده شده‌اند."}],"organised":[{"en":"No clear paragraphs.","tr":"Net paragraflar yok.","fa":"پاراگراف‌های روشنی ندارد."},{"en":"Paragraphs, but more than one main idea in each, or forced linking words.","tr":"Paragraflar var ama her birinde birden fazla ana fikir ya da zorlama bağlaçlar.","fa":"پاراگراف دارد، اما در هر کدام بیش از یک ایده‌ی اصلی هست یا کلمه‌های ربط تصنعی‌اند."},{"en":"Introduction, body paragraphs with one idea each, conclusion.","tr":"Giriş, her biri tek fikirli gövde paragrafları, sonuç.","fa":"مقدمه، پاراگراف‌هایی که هر کدام یک ایده دارند، نتیجه."},{"en":"A logical flow from start to end; linking is natural.","tr":"Baştan sona mantıklı bir akış; bağlantılar doğal.","fa":"جریانی منطقی از اول تا آخر؛ ربط‌ها طبیعی‌اند."}],"words":[{"en":"Very basic words; the question is copied.","tr":"Çok temel kelimeler; soru kopyalanmış.","fa":"کلمه‌های خیلی ساده؛ صورت سؤال کپی شده."},{"en":"Topic words repeated; some wrong word choices.","tr":"Konu kelimeleri tekrarlanmış; bazı yanlış kelime seçimleri.","fa":"کلمه‌های موضوع تکرار شده‌اند؛ چند انتخاب کلمه‌ی غلط هست."},{"en":"Topic words used well; the question is said in other words.","tr":"Konu kelimeleri iyi kullanılmış; soru başka sözcüklerle anlatılmış.","fa":"کلمه‌های موضوع خوب به کار رفته‌اند؛ سؤال با کلمه‌های دیگر بیان شده."},{"en":"Precise, natural topic words; almost no errors.","tr":"Yerinde, doğal konu kelimeleri; neredeyse hatasız.","fa":"کلمه‌های موضوعِ دقیق و طبیعی؛ تقریباً بی‌غلط."}],"sentences":[{"en":"Mostly short sentences with frequent errors.","tr":"Çoğunlukla kısa cümleler, sık hatalar.","fa":"بیشتر جمله‌های کوتاه با غلط‌های زیاد."},{"en":"Some longer sentences; errors sometimes make the meaning unclear.","tr":"Bazı uzun cümleler; hatalar bazen anlamı belirsizleştiriyor.","fa":"چند جمله‌ی بلندتر؛ غلط‌ها گاهی معنی را نامفهوم می‌کنند."},{"en":"A mix of sentence types; errors rarely affect the meaning.","tr":"Çeşitli cümle türleri; hatalar anlamı nadiren etkiliyor.","fa":"ترکیبی از انواع جمله؛ غلط‌ها به‌ندرت روی معنی اثر می‌گذارند."},{"en":"A wide range of sentences, almost all accurate.","tr":"Çok çeşitli cümleler, neredeyse hepsi doğru.","fa":"جمله‌های خیلی متنوع، تقریباً همه درست."}]},"type":"writing","id":"c-x01-w2-w","course":"ielts-exams","exam":"exam-01","unit":"x01-w2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"A housing shortage\" means...","options":["there are not enough homes for the people who need them","homes are too small","houses are too old"],"correct":0,"why":{"en":"A shortage = not enough of something.","tr":"Shortage = bir şeyin yeterince olmaması.","fa":"shortage یعنی کمبود، به اندازه‌ی کافی نبودن."}},{"tests":"paraphrase","point":3,"prompt":"Which phrase does NOT copy the words \"tall apartment blocks\" from the question?","options":["tall apartment blocks","apartment blocks that are tall","high-rise towers"],"correct":2,"why":{"en":"\"High-rise towers\" says the same thing in other words; the other two repeat the question.","tr":"\"High-rise towers\" aynı şeyi başka kelimelerle söylüyor; diğer ikisi soruyu tekrarlıyor.","fa":"«high-rise towers» همان معنی را با کلمه‌های دیگر می‌گوید؛ دو گزینه‌ی دیگر سؤال را تکرار می‌کنند."}},{"tests":"method","point":2,"prompt":"How should you use the first five minutes of Task 2?","options":["Start writing the introduction at once","Plan: position, two reasons, an example for each","Count how many words you need"],"correct":1,"why":{"en":"A five-minute plan keeps one position and gives each paragraph one job.","tr":"Beş dakikalık bir plan tek bir tutumu korur ve her paragrafa tek bir iş verir.","fa":"برنامه‌ی پنج‌دقیقه‌ای یک موضع را حفظ می‌کند و به هر پاراگراف یک کار می‌دهد."}},{"tests":"trap","point":1,"prompt":"An essay agrees with the claim in the introduction and disagrees with it in the conclusion. What is the problem?","options":["The position changes, so the question is not clearly answered","The conclusion is too short","There are too many examples"],"correct":0,"why":{"en":"The reader must know your answer from the first paragraph to the last.","tr":"Okur cevabını ilk paragraftan sonuncuya kadar bilmeli.","fa":"خواننده باید جوابت را از پاراگراف اول تا آخر بداند."}}],"id":"c-x01-w2-x","course":"ielts-exams","exam":"exam-01","unit":"x01-w2"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
